<?php
require_once __DIR__.'/includes/auth.php';require_permission('dashboard');$pdo=db();
if(current_user()['role']!=='admin'){http_response_code(403);exit('Only administrators can manage staff accounts.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['form_action']??'';$id=(int)($_POST['id']??0);if($action==='save'){$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$username=trim($_POST['username']??'');$role=$_POST['role']??'staff';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$name===''||$username===''){flash('error','Name, valid email, and username are required.');redirect('staff_accounts.php');}$allowed=['admin','staff','records_officer','blotter_officer','treasurer'];if(!in_array($role,$allowed,true))$role='staff';if($id){$sql='UPDATE users SET full_name=?,email=?,username=?,role=?,account_status=?'.(!empty($_POST['password'])?',password_hash=?':'').' WHERE id=? AND role<>\'resident\'';$p=[$name,$email,$username,$role,$_POST['account_status']??'active'];if(!empty($_POST['password']))$p[]=password_hash($_POST['password'],PASSWORD_DEFAULT);$p[]=$id;$pdo->prepare($sql)->execute($p);audit_action('staff_updated','users',$id,'Role: '.$role);flash('success','Staff account updated.');}else{if(strlen($_POST['password']??'')<8){flash('error','New staff passwords must contain at least 8 characters.');redirect('staff_accounts.php');}$pdo->prepare('INSERT INTO users (full_name,email,username,password_hash,role,account_status) VALUES (?,?,?,?,?,?)')->execute([$name,$email,$username,password_hash($_POST['password'],PASSWORD_DEFAULT),$role,$_POST['account_status']??'active']);audit_action('staff_created','users',(int)$pdo->lastInsertId(),'Role: '.$role);flash('success','Staff account created.');}redirect('staff_accounts.php');}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM users WHERE id=? AND role<>'resident'");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$accounts=$pdo->query("SELECT * FROM users WHERE role<>'resident' ORDER BY created_at DESC")->fetchAll();$pageTitle='Staff accounts';$activePage='staff';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Administration / Access</div><h1>Staff accounts</h1><p>Create role-based official accounts without deleting historical staff records.</p></div><a class="primary-button" href="staff_accounts.php?action=new">＋ Add staff account</a></section><div class="priority-banner retention-safe"><span class="priority-icon">✓</span><div><strong>Protected staff identities</strong><small>Staff accounts can be suspended or expired, but they are never deleted.</small></div></div><?php if(($_GET['action']??'')==='new'||$edit): ?><section class="panel form-panel"><div class="card-header"><h2><?= $edit?'Edit staff account':'Add staff account' ?></h2><a class="text-button" href="staff_accounts.php">Close ×</a></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="save"><input type="hidden" name="id" value="<?= h($edit['id']??'') ?>"><label>Full name<input name="full_name" required value="<?= h($edit['full_name']??'') ?>"></label><label>Email<input type="email" name="email" required value="<?= h($edit['email']??'') ?>"></label><label>Username<input name="username" required value="<?= h($edit['username']??'') ?>"></label><label>Password<input type="password" name="password" <?= $edit?'':'required' ?> minlength="8" placeholder="<?= $edit?'Leave blank to keep current':'' ?>"></label><label>Role<select name="role"><?php foreach(['admin','staff','records_officer','blotter_officer','treasurer'] as $role): ?><option value="<?= h($role) ?>" <?= (($edit['role']??'staff')===$role)?'selected':'' ?>><?= h(ucwords(str_replace('_',' ',$role))) ?></option><?php endforeach; ?></select></label><label>Status<select name="account_status"><option value="active">Active</option><option value="suspended" <?= (($edit['account_status']??'')==='suspended')?'selected':'' ?>>Suspended</option><option value="expired" <?= (($edit['account_status']??'')==='expired')?'selected':'' ?>>Expired</option></select></label><div class="form-actions"><a class="secondary-button" href="staff_accounts.php">Cancel</a><button class="primary-button">Save staff account</button></div></form></section><?php endif; ?><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">Official access registry</div><h2>Staff and administrators</h2></div><span class="muted"><?= count($accounts) ?> accounts</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email / username</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($accounts as $account): ?><tr><td><strong><?= h($account['full_name']) ?></strong></td><td><?= h($account['email']) ?><small class="cell-subtext mono"><?= h($account['username']) ?></small></td><td><?= h(ucwords(str_replace('_',' ',$account['role']))) ?></td><td><span class="status-pill <?= h($account['account_status']) ?>"><i></i><?= h(ucfirst($account['account_status'])) ?></span></td><td><a class="text-button" href="staff_accounts.php?edit=<?= h($account['id']) ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php'; ?>
